import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-079","description":"","frontmatter":{"date":"2020-10-22T19:35:13","title":"写作课作业-079","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/079.md","filePath":"posts/homework/079.md"}'),l={name:"posts/homework/079.md"};function s(p,e,i,n,c,_){return a(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p>10.6写作作业：《微信互联网平民创业》之《11. 平民如何做好视频号内容?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>去中心化。微信视频号的最重要特征之一就是它的“去中心化”属性。平民么，只有在“分布式网络”里才有真正属于自己的机会。</p><p>平民本色。想要做好视频号，最重要的应该排第一名的就是平民本色。你的本色就是你的特色，你的本色和特色就是你的优势 —— 不要去模仿他人，不要去跟⻛，保持本色才是最大的⻓期核心竞争力。</p><p>优质内容。吸引人的，永远不是拍摄技术本身，永远是内容，准确地讲，是优质内容；更准确地讲，是优质内容所传递的真正价值。</p><p>价值导向。价值导向让我们提取出这其中最为重要的关键字：有趣、有用</p><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>虽然自己还没有做视频号，但从“有用，有趣”的角度去思考问题，即使是自己教程，写公众号文章都应该能从中受益。</p><p>平民本色，更多的是要能正确的认识自己，在《批评性思维》里，就有专门的一章说“你是谁”？在正确认识自己之后，保持本色能让自己更容易保持长期。</p>',9)])])}const m=t(l,[["render",s]]);export{h as __pageData,m as default};
